from itertools import product
import heapq


def _ledger(data, sequence_first, original_tax):
    mode = data.get("rounding", "floor")

    def rounded(n, d=10000):
        if mode == "half_up":
            return (n + d // 2) // d
        return n // d

    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if sequence_first:
            rank = (seq, event.get("revision", 0), pos)
        else:
            rank = (event.get("revision", 0), pos)
        if event_id not in chosen or rank > chosen[event_id][0]:
            chosen[event_id] = (rank, event)

    balances = dict(data.get("opening", {}))
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        base = raw if original_tax else net
        tax = rounded(base * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _build_component_01():
    return lambda data: _ledger(data, True, True)


def _build_component_02():
    return lambda data: _ledger(data, False, False)


def _build_component_03():
    return lambda data: _ledger(data, True, False)


def _build_component_04():
    return lambda data: _ledger(data, False, True)


def _build_component_05():
    return lambda data: _ledger(data, True, True)


def _build_component_06():
    def solve(data):
        packages = data["packages"]
        names = list(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        options = []
        for name in names:
            versions = []
            for row in packages[name]:
                version = row["version"]
                if version in blocked.get(name, []):
                    continue
                if name in pins and version != pins[name]:
                    continue
                versions.append(version)
            options.append([None] + versions)

        best_vector = None
        best_install = None
        order = sorted(names, reverse=True)
        for choice in product(*options):
            install = {name: version for name, version in zip(names, choice)
                       if version is not None}
            valid = True
            for name, bounds in roots.items():
                if name not in install or not bounds[0] <= install[name] <= bounds[1]:
                    valid = False
                    break
            if not valid:
                continue

            edges = {name: [] for name in install}
            for name, version in install.items():
                row = next(r for r in packages[name] if r["version"] == version)
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    if target not in install or not dep["min"] <= install[target] <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(target)
                if not valid:
                    break
            if not valid:
                continue

            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges.get(name, []))
            if reachable != set(install):
                continue

            active, finished = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(other) for other in edges.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in install):
                continue
            vector = tuple(install.get(name, -1) for name in order)
            if best_vector is None or vector < best_vector:
                best_vector, best_install = vector, install

        if best_install is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_install}
    return solve


def _build_component_07():
    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        available = [job for job in jobs if job["id"] not in blocked]

        for mask in range(1 << len(available)):
            if mask.bit_count() != k:
                continue
            selected = [available[i] for i in range(len(available)) if mask >> i & 1]
            ids = tuple(sorted(job["id"] for job in selected))
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in selected:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(selected, key=lambda job: (job["start"], job["end"]))
            if any(ordered[i]["start"] < ordered[i - 1]["end"]
                   for i in range(1, len(ordered))):
                continue
            value = sum(job["value"] for job in selected)
            if (best_value is None or value > best_value or
                    (value == best_value and ids > best_ids)):
                best_value, best_ids = value, ids

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_component_08():
    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        source = data["source"]
        initial_mask = bit_for.get(source, 0)
        initial = (source, data["coupons"], initial_mask)
        distances = {initial: data["start"]}
        queue = [(data["start"], source, data["coupons"], initial_mask)]

        while queue:
            time, node, remaining, mask = heapq.heappop(queue)
            state = (node, remaining, mask)
            if distances.get(state) != time:
                continue
            if node == data["target"] and remaining == 0 and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                moves = [(edge["duration"], remaining)]
                if remaining:
                    duration = max(1, edge["duration"] - edge.get("discount", 0))
                    moves.append((duration, remaining - 1))
                for duration, next_remaining in moves:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = edge["v"]
                    next_mask = mask | bit_for.get(nxt, 0)
                    next_state = (nxt, next_remaining, next_mask)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, nxt, next_remaining, next_mask))
        return {"arrival": None}
    return solve


SOLVERS = {
    "component_01": _build_component_01(),
    "component_02": _build_component_02(),
    "component_03": _build_component_03(),
